import { describe, it, expect } from "vitest";
import { drawEntity } from "./assets.js";
import { config } from "./config.js";

// Minimal 2D context stand-in that records the glow state at fill time.
function fakeCtx() {
  const fills: number[] = [];
  const ctx = {
    shadowBlur: 0, shadowColor: "", fillStyle: "",
    save() {}, restore() { ctx.shadowBlur = 0; },
    beginPath() {}, arc() {}, fill() {},
    fillRect() { fills.push(ctx.shadowBlur); },
  };
  return { ctx: ctx as unknown as CanvasRenderingContext2D, fills };
}

describe("pellet glow", () => {
  it("draws every pellet with config.pelletGlow and restores the context", () => {
    const { ctx, fills } = fakeCtx();
    for (let i = 0; i < 3; i++) drawEntity(ctx, { id: `p${i}`, kind: "pellet", x: i * 10, y: 5, r: 2 } as never);
    expect(config.pelletGlow).toBeGreaterThan(0);
    expect(fills).toEqual([config.pelletGlow, config.pelletGlow, config.pelletGlow]);
    expect(ctx.shadowBlur).toBe(0);
  });
});
